#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <climits>
int main(int argc,char**argv){assert(argc==3);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]);ofstream out(argv[2]),meta(string(argv[2])+".meta");int n,m;in>>n>>m;assert(n==m);vector<Row>A(n);vector<vector<long>>cost(n,vector<long>(n,100000));ulong ex[2];for(int i=0;i<n;i++){int nn;in>>nn;for(int k=0;k<nn;k++){int j;Rat a;in>>j;readpoly(in,a.n);long v=100000;for(long t=0;t<fmpq_mpoly_length(a.n,ctx);t++){fmpq_mpoly_get_term_exp_ui(ex,a.n,t,ctx);v=min(v,long(ex[1]));}cost[i][j]=v;A[i].emplace(j,std::move(a));}}
 vector<long>u(n+1),v(n+1);vector<int>p(n+1),way(n+1);for(int i=1;i<=n;i++){p[0]=i;int j0=0;vector<long>minv(n+1,LONG_MAX/4);vector<char>used(n+1);do{used[j0]=true;int i0=p[j0],j1=0;long delta=LONG_MAX/4;for(int j=1;j<=n;j++)if(!used[j]){long cur=cost[i0-1][j-1]-u[i0]-v[j];if(cur<minv[j]){minv[j]=cur;way[j]=j0;}if(minv[j]<delta){delta=minv[j];j1=j;}}for(int j=0;j<=n;j++)if(used[j]){u[p[j]]+=delta;v[j]-=delta;}else minv[j]-=delta;j0=j1;}while(p[j0]);do{int j1=way[j0];p[j0]=p[j1];j0=j1;}while(j0);}long val=0;for(int i=1;i<=n;i++){assert(cost[p[i]-1][i-1]<10000);val+=u[i]+v[i];}meta<<"VALUATION "<<val<<'\n';for(int i=1;i<=n;i++)meta<<u[i]<<' ';meta<<'\n';for(int j=1;j<=n;j++)meta<<v[j]<<' ';meta<<'\n';out<<n<<' '<<n<<'\n';Rat x,pow,q;fmpq_mpoly_gen(x.n,1,ctx);for(int i=0;i<n;i++){out<<A[i].size()<<'\n';for(auto&[j,a]:A[i]){long d=u[i+1]+v[j+1];assert(d<=cost[i][j]);fmpq_mpoly_pow_ui(pow.n,x.n,abs(d),ctx);if(d>=0)assert(fmpq_mpoly_divides(q.n,a.n,pow.n,ctx));else fmpq_mpoly_mul(q.n,a.n,pow.n,ctx);out<<j<<'\n';writepoly(out,q.n);}}cerr<<"TROPICAL_EXACT_VALUATION "<<val<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
